let filtered = data.filter(
    entry => entry.timeCreated > global.get("last_rayvn_timestamp")
    )

msg.payload = filtered

return msg;

let data = msg.payload

// Exclude entries that have the WaSOS label (they came from WaSOS)
const labelName = "WaSOS";

const filtered = data.filter(
    entry => !entry.labels.some(label => label.name === labelName)
);

msg.payload = filtered

return msg;

if (msg.payload && msg.payload.length > 0) {
    return msg;
}
else {
    return null;
}
